out.print("<scr"+"ipt>");

      out.write("\r\n");
      out.write("/* ─── In-memory product store ─────────────────────────────── */\r\n");
      out.write("let products = [\r\n");
      out.write("  { id:1, name:\"Casio Edifice EF-539D\",   brand:\"Casio\",    categoryId:3, categoryName:\"Sport\",   price:12500, oldPrice:14000, rating:4.5, inStock:true,  imageUrl:\"\", description:\"Rugged sport chronograph.\" },\r\n");
      out.write("  { id:2, name:\"Seiko Presage SRPE35\",     brand:\"Seiko\",    categoryId:1, categoryName:\"Luxury\",  price:52000, oldPrice:0,     rating:4.8, inStock:true,  imageUrl:\"\", description:\"Automatic prestige piece.\" },\r\n");
      out.write("  { id:3, name:\"Citizen Eco-Drive AT2480\", brand:\"Citizen\",  categoryId:2, categoryName:\"Casual\",  price:24500, oldPrice:27000, rating:4.3, inStock:false, imageUrl:\"\", description:\"Solar-powered everyday watch.\" },\r\n");
      out.write("  { id:4, name:\"Tissot PRX Powermatic\",    brand:\"Tissot\",   categoryId:1, categoryName:\"Luxury\",  price:85000, oldPrice:0,     rating:4.7, inStock:true,  imageUrl:\"\", description:\"Swiss automatic, tapisserie dial.\" },\r\n");
      out.write("  { id:5, name:\"Orient Bambino V4\",        brand:\"Orient\",   categoryId:5, categoryName:\"Classic\", price:18500, oldPrice:20000, rating:4.4, inStock:true,  imageUrl:\"\", description:\"Hand-wound dress watch.\" },\r\n");
      out.write("  { id:6, name:\"Fossil Gen 6 Smartwatch\",  brand:\"Fossil\",   categoryId:4, categoryName:\"Smart\",   price:32000, oldPrice:36000, rating:4.0, inStock:true,  imageUrl:\"\", description:\"Wear OS smartwatch.\" },\r\n");
      out.write("  { id:7, name:\"G-Shock GA-2100\",          brand:\"Casio\",    categoryId:3, categoryName:\"Sport\",   price:15000, oldPrice:0,     rating:4.6, inStock:false, imageUrl:\"\", description:\"Ultra-thin CasiOak.\" },\r\n");
      out.write("  { id:8, name:\"Hamilton Khaki Field Auto\",brand:\"Hamilton\", categoryId:5, categoryName:\"Classic\", price:125000,oldPrice:0,     rating:4.9, inStock:true,  imageUrl:\"\", description:\"Military-inspired automatic.\" },\r\n");
      out.write("];\r\n");
      out.write("let nextId = 9;\r\n");
      out.write("\r\n");
      out.write("/* ─── Section switching ──────────────────────────────────── */\r\n");
      out.write("const sectionIds = ['dashboard','products','orders','customers','sales','inventory'];\r\n");
      out.write("const sectionTitles = {\r\n");
      out.write("  dashboard:'Dashboard', products:'Product Management',\r\n");
      out.write("  orders:'Orders', customers:'Customers', sales:'Sales Report', inventory:'Inventory'\r\n");
      out.write("};\r\n");
      out.write("\r\n");
      out.write("function showSection(id, el) {\r\n");
      out.write("  sectionIds.forEach(function(s) {\r\n");
      out.write("    const sec = document.getElementById('sec-' + s);\r\n");
      out.write("    if (sec) sec.style.display = s === id ? '' : 'none';\r\n");
      out.write("  });\r\n");
      out.write("  document.querySelectorAll('.adm-nav-item').forEach(function(a) { a.classList.remove('active'); });\r\n");
      out.write("  if (el) el.classList.add('active');\r\n");
      out.write("  document.getElementById('topbarTitle').textContent = sectionTitles[id] || id;\r\n");
      out.write("  if (id === 'products') { renderProdMgmt(products); }\r\n");
      out.write("  if (id === 'sales' && !salesChart2) { buildSalesChart2(); }\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("/* ─── Escape single quotes for inline onclick attrs ─────── */\r\n");
      out.write("function esc(s) { return s.split(\"'\").join(\"&#39;\"); }\r\n");
      out.write("\r\n");
      out.write("/* ─── Table row builder ──────────────────────────────────── */\r\n");
      out.write("function buildRow(p, cols9) {\r\n");
      out.write("  const imgCell = p.imageUrl\r\n");
      out.write("    ? '<img src=\"' + p.imageUrl + '\" style=\"width:44px;height:44px;border-radius:10px;object-fit:cover;border:1.5px solid var(--border);\">'\r\n");
      out.write("    : '<div class=\"td-thumb\">&#8987;</div>';\r\n");
      out.write("  const stockCell = p.inStock\r\n");
      out.write("    ? '<span class=\"stock-yes\">In Stock</span>'\r\n");
      out.write("    : '<span class=\"stock-no\">Out of Stock</span>';\r\n");
      out.write("  const ratingCell = '<span style=\"color:var(--gold);font-size:.78rem;\">&#9733;</span> <span style=\"font-size:.76rem;font-weight:700;\">' + p.rating + '</span>';\r\n");
      out.write("  const safeNameJs = esc(p.name);\r\n");
      out.write("  const actions = '<div class=\"tbl-actions\">'\r\n");
      out.write("    + '<button class=\"tbl-btn tbl-btn-edit\" onclick=\"openEditModal(' + p.id + ')\">&#9998; Edit</button>'\r\n");
      out.write("    + '<button class=\"tbl-btn tbl-btn-del\" onclick=\"openDelModal(' + p.id + ',\\'' + safeNameJs + '\\')\">&#128465;</button>'\r\n");
      out.write("    + '</div>';\r\n");
      out.write("  const oldPriceCell = p.oldPrice ? 'Rs ' + p.oldPrice.toLocaleString() : '&mdash;';\r\n");
      out.write("  const descCell = p.description ? p.description.slice(0, 36) + '&hellip;' : '&mdash;';\r\n");
      out.write("\r\n");
      out.write("  if (cols9) {\r\n");
      out.write("    return '<tr>'\r\n");
      out.write("      + '<td style=\"color:var(--dim);font-size:.75rem;\">' + p.id + '</td>'\r\n");
      out.write("      + '<td><div style=\"display:flex;align-items:center;gap:.75rem;\">' + imgCell + '<div><div class=\"td-name\">' + p.name + '</div><div class=\"td-desc\">' + descCell + '</div></div></div></td>'\r\n");
      out.write("      + '<td>' + p.brand + '</td>'\r\n");
      out.write("      + '<td><span class=\"cat-pill\">' + p.categoryName + '</span></td>'\r\n");
      out.write("      + '<td class=\"td-price\">Rs ' + p.price.toLocaleString() + '</td>'\r\n");
      out.write("      + '<td style=\"font-size:.78rem;color:var(--muted);text-decoration:line-through;\">' + oldPriceCell + '</td>'\r\n");
      out.write("      + '<td>' + stockCell + '</td>'\r\n");
      out.write("      + '<td>' + ratingCell + '</td>'\r\n");
      out.write("      + '<td>' + actions + '</td>'\r\n");
      out.write("      + '</tr>';\r\n");
      out.write("  } else {\r\n");
      out.write("    return '<tr>'\r\n");
      out.write("      + '<td style=\"color:var(--dim);font-size:.75rem;\">' + p.id + '</td>'\r\n");
      out.write("      + '<td><div style=\"display:flex;align-items:center;gap:.75rem;\">' + imgCell + '<div><div class=\"td-name\">' + p.name + '</div><div class=\"td-desc\">' + descCell + '</div></div></div></td>'\r\n");
      out.write("      + '<td>' + p.brand + '</td>'\r\n");
      out.write("      + '<td><span class=\"cat-pill\">' + p.categoryName + '</span></td>'\r\n");
      out.write("      + '<td class=\"td-price\">Rs ' + p.price.toLocaleString() + '</td>'\r\n");
      out.write("      + '<td>' + stockCell + '</td>'\r\n");
      out.write("      + '<td>' + ratingCell + '</td>'\r\n");
      out.write("      + '<td>' + actions + '</td>'\r\n");
      out.write("      + '</tr>';\r\n");
      out.write("  }\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("/* ─── Dashboard table ────────────────────────────────────── */\r\n");
      out.write("function renderDashTable(list) {\r\n");
      out.write("  const tbody = document.getElementById('dashTbody');\r\n");
      out.write("  document.getElementById('dashProductCount').textContent =\r\n");
      out.write("    list.length + ' product' + (list.length !== 1 ? 's' : '') + ' in catalogue';\r\n");
      out.write("  updateKpi();\r\n");
      out.write("  if (!list.length) {\r\n");
      out.write("    tbody.innerHTML = '<tr><td colspan=\"8\" style=\"text-align:center;padding:3rem;color:var(--muted);\">No products found.</td></tr>';\r\n");
      out.write("    return;\r\n");
      out.write("  }\r\n");
      out.write("  tbody.innerHTML = list.map(function(p) { return buildRow(p, false); }).join('');\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("function filterDashTable() {\r\n");
      out.write("  const q = document.getElementById('dashSearch').value.toLowerCase();\r\n");
      out.write("  renderDashTable(q ? products.filter(function(p) {\r\n");
      out.write("    return p.name.toLowerCase().indexOf(q) !== -1 || p.brand.toLowerCase().indexOf(q) !== -1 || p.categoryName.toLowerCase().indexOf(q) !== -1;\r\n");
      out.write("  }) : products);\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("/* ─── Products management table ─────────────────────────── */\r\n");
      out.write("function renderProdMgmt(list) {\r\n");
      out.write("  const tbody = document.getElementById('prodMgmtTbody');\r\n");
      out.write("  const inStock = list.filter(function(p) { return p.inStock; }).length;\r\n");
      out.write("  document.getElementById('prodMgmtCount').textContent = list.length + ' products';\r\n");
      out.write("  document.getElementById('pStatTotal').textContent   = list.length;\r\n");
      out.write("  document.getElementById('pStatInStock').textContent = inStock;\r\n");
      out.write("  document.getElementById('pStatOut').textContent     = list.length - inStock;\r\n");
      out.write("  if (!list.length) {\r\n");
      out.write("    tbody.innerHTML = '<tr><td colspan=\"9\" style=\"text-align:center;padding:3rem;color:var(--muted);\">No products found.</td></tr>';\r\n");
      out.write("    return;\r\n");
      out.write("  }\r\n");
      out.write("  tbody.innerHTML = list.map(function(p) { return buildRow(p, true); }).join('');\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("function filterProdTable() {\r\n");
      out.write("  const q   = document.getElementById('prodSearch').value.toLowerCase();\r\n");
      out.write("  const cat = document.getElementById('filterCat').value;\r\n");
      out.write("  let list  = products;\r\n");
      out.write("  if (cat) list = list.filter(function(p) { return p.categoryName === cat; });\r\n");
      out.write("  if (q)   list = list.filter(function(p) { return p.name.toLowerCase().indexOf(q) !== -1 || p.brand.toLowerCase().indexOf(q) !== -1; });\r\n");
      out.write("  renderProdMgmt(list);\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("/* ─── Top Products list ───────────────────────────────────── */\r\n");
      out.write("const topColors = ['var(--green)','var(--gold)','#3b82f6','#7c3aed','#d97706'];\r\n");
      out.write("function renderTopProducts() {\r\n");
      out.write("  const sorted = products.slice().sort(function(a, b) { return b.price - a.price; }).slice(0, 5);\r\n");
      out.write("  document.getElementById('topProductsList').innerHTML = sorted.map(function(p, i) {\r\n");
      out.write("    return '<div class=\"qs-item\">'\r\n");
      out.write("      + '<div class=\"qs-left\">'\r\n");
      out.write("      + '<div class=\"qs-dot\" style=\"background:' + topColors[i] + '\"></div>'\r\n");
      out.write("      + '<div><div class=\"qs-name\">' + p.name + '</div><div class=\"qs-cat\">' + p.brand + ' &middot; ' + p.categoryName + '</div></div>'\r\n");
      out.write("      + '</div>'\r\n");
      out.write("      + '<div class=\"qs-val\">Rs ' + p.price.toLocaleString() + '</div>'\r\n");
      out.write("      + '</div>';\r\n");
      out.write("  }).join('');\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("/* ─── KPI update ─────────────────────────────────────────── */\r\n");
      out.write("function updateKpi() {\r\n");
      out.write("  const c = products.filter(function(p) { return p.inStock; }).length;\r\n");
      out.write("  document.getElementById('kpiStockCount').textContent = c;\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("/* ─── Add / Edit Modal ───────────────────────────────────── */\r\n");
      out.write("function openAddModal() {\r\n");
      out.write("  document.getElementById('modalTitle').textContent = 'Add New Product';\r\n");
      out.write("  document.getElementById('modalSaveBtn').textContent = '✓ Save Product';\r\n");
      out.write("  clearForm();\r\n");
      out.write("  document.getElementById('productModal').classList.add('open');\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("function openEditModal(id) {\r\n");
      out.write("  const p = products.find(function(x) { return x.id === id; });\r\n");
      out.write("  if (!p) return;\r\n");
      out.write("  document.getElementById('modalTitle').textContent = 'Edit Product';\r\n");
      out.write("  document.getElementById('modalSaveBtn').textContent = '✓ Update Product';\r\n");
      out.write("  document.getElementById('pId').value       = p.id;\r\n");
      out.write("  document.getElementById('pName').value     = p.name;\r\n");
      out.write("  document.getElementById('pBrand').value    = p.brand;\r\n");
      out.write("  document.getElementById('pPrice').value    = p.price;\r\n");
      out.write("  document.getElementById('pOldPrice').value = p.oldPrice || '';\r\n");
      out.write("  document.getElementById('pCategory').value = p.categoryId;\r\n");
      out.write("  document.getElementById('pRating').value   = p.rating;\r\n");
      out.write("  document.getElementById('pDesc').value     = p.description;\r\n");
      out.write("  document.getElementById('pImg').value      = p.imageUrl;\r\n");
      out.write("  document.getElementById('pStock').checked  = p.inStock;\r\n");
      out.write("  document.getElementById('productModal').classList.add('open');\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("function closeProductModal() { document.getElementById('productModal').classList.remove('open'); }\r\n");
      out.write("\r\n");
      out.write("function clearForm() {\r\n");
      out.write("  ['pId','pName','pBrand','pPrice','pOldPrice','pDesc','pImg','pRating'].forEach(function(id) { document.getElementById(id).value = ''; });\r\n");
      out.write("  document.getElementById('pCategory').value = '';\r\n");
      out.write("  document.getElementById('pStock').checked  = true;\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("const catNames = {'1':'Luxury','2':'Casual','3':'Sport','4':'Smart','5':'Classic'};\r\n");
      out.write("\r\n");
      out.write("function saveProduct() {\r\n");
      out.write("  const name  = document.getElementById('pName').value.trim();\r\n");
      out.write("  const brand = document.getElementById('pBrand').value.trim();\r\n");
      out.write("  const price = parseFloat(document.getElementById('pPrice').value);\r\n");
      out.write("  const catId = document.getElementById('pCategory').value;\r\n");
      out.write("  if (!name || !brand || isNaN(price) || !catId) {\r\n");
      out.write("    showToast('Please fill all required fields.', 'error'); return;\r\n");
      out.write("  }\r\n");
      out.write("  const id     = document.getElementById('pId').value;\r\n");
      out.write("  const isEdit = !!id;\r\n");
      out.write("  const obj = {\r\n");
      out.write("    id:           isEdit ? parseInt(id) : nextId++,\r\n");
      out.write("    name: name, brand: brand,\r\n");
      out.write("    categoryId:   parseInt(catId),\r\n");
      out.write("    categoryName: catNames[catId] || catId,\r\n");
      out.write("    price:        price,\r\n");
      out.write("    oldPrice:     parseFloat(document.getElementById('pOldPrice').value) || 0,\r\n");
      out.write("    rating:       parseFloat(document.getElementById('pRating').value) || 0,\r\n");
      out.write("    description:  document.getElementById('pDesc').value.trim(),\r\n");
      out.write("    imageUrl:     document.getElementById('pImg').value.trim(),\r\n");
      out.write("    inStock:      document.getElementById('pStock').checked,\r\n");
      out.write("  };\r\n");
      out.write("  if (isEdit) {\r\n");
      out.write("    const idx = products.findIndex(function(x) { return x.id === obj.id; });\r\n");
      out.write("    if (idx !== -1) products[idx] = obj;\r\n");
      out.write("    showToast('Product updated successfully!', 'success');\r\n");
      out.write("  } else {\r\n");
      out.write("    products.push(obj);\r\n");
      out.write("    showToast('Product added successfully!', 'success');\r\n");
      out.write("  }\r\n");
      out.write("  closeProductModal();\r\n");
      out.write("  renderDashTable(products);\r\n");
      out.write("  renderTopProducts();\r\n");
      out.write("  renderProdMgmt(products);\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("/* ─── Delete Modal ───────────────────────────────────────── */\r\n");
      out.write("let deletingId = null;\r\n");
      out.write("function openDelModal(id, name) {\r\n");
      out.write("  deletingId = id;\r\n");
      out.write("  document.getElementById('delProdName').textContent = name;\r\n");
      out.write("  document.getElementById('delModal').classList.add('open');\r\n");
      out.write("  document.getElementById('delConfirmBtn').onclick = confirmDelete;\r\n");
      out.write("}\r\n");
      out.write("function closeDelModal() { document.getElementById('delModal').classList.remove('open'); deletingId = null; }\r\n");
      out.write("function confirmDelete() {\r\n");
      out.write("  if (!deletingId) return;\r\n");
      out.write("  products = products.filter(function(p) { return p.id !== deletingId; });\r\n");
      out.write("  closeDelModal();\r\n");
      out.write("  renderDashTable(products);\r\n");
      out.write("  renderTopProducts();\r\n");
      out.write("  renderProdMgmt(products);\r\n");
      out.write("  showToast('Product deleted.', 'error');\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("/* ─── Toast ──────────────────────────────────────────────── */\r\n");
      out.write("function showToast(msg, type) {\r\n");
      out.write("  type = type || '';\r\n");
      out.write("  const c = document.getElementById('toastContainer');\r\n");
      out.write("  const t = document.createElement('div');\r\n");
      out.write("  t.className = 'toast ' + type;\r\n");
      out.write("  const ico = type === 'success' ? '✓' : type === 'error' ? '✕' : 'ℹ';\r\n");
      out.write("  t.innerHTML = '<span class=\"toast-ico\">' + ico + '</span> ' + msg;\r\n");
      out.write("  c.appendChild(t);\r\n");
      out.write("  setTimeout(function() {\r\n");
      out.write("    t.style.opacity = '0'; t.style.transform = 'translateX(22px)'; t.style.transition = 'all .3s';\r\n");
      out.write("    setTimeout(function() { t.remove(); }, 320);\r\n");
      out.write("  }, 2800);\r\n");
      out.write("}\r\n");
      out.write("\r\n");
      out.write("/* ─── Chart utils ────────────────────────────────────────── */\r\n");
      out.write("const rand = function(a, b) { return Math.floor(Math.random() * (b - a + 1)) + a; };\r\n");
      out.write("const genData = function(n) { return Array.from({length: n}, function() { return rand(8000, 55000); }); };\r\n");
      out.write("const labels7  = ['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];\r\n");
      out.write("const labels14 = Array.from({length:14}, function(_, i) { return 'Day ' + (i+1); });\r\n");
      out.write("const labels30 = Array.from({length:30}, function(_, i) { return 'Day ' + (i+1); });\r\n");
      out.write("const getLabels = function(n) { return n === 7 ? labels7 : n === 14 ? labels14 : labels30; };\r\n");
      out.write("\r\n");
      out.write("function chartConfig(n) {\r\n");
      out.write("  return {\r\n");
      out.write("    type: 'line',\r\n");
      out.write("    data: {\r\n");
      out.write("      labels: getLabels(n),\r\n");
      out.write("      datasets: [{\r\n");
      out.write("        label: 'Revenue (Rs)',\r\n");
      out.write("        data: genData(n),\r\n");
      out.write("        borderColor: '#1a6b38',\r\n");
      out.write("        backgroundColor: 'rgba(26,107,56,0.08)',\r\n");
      out.write("        fill: true, tension: 0.42,\r\n");
      out.write("        pointRadius: 4, pointBackgroundColor: '#1a6b38',\r\n");
      out.write("        pointBorderColor: '#fff', pointBorderWidth: 2, pointHoverRadius: 6,\r\n");
      out.write("      }]\r\n");
      out.write("    },\r\n");
      out.write("    options: {\r\n");
      out.write("      responsive: true, maintainAspectRatio: false,\r\n");
      out.write("      interaction: { mode: 'index', intersect: false },\r\n");
      out.write("      plugins: {\r\n");
      out.write("        legend: { display: false },\r\n");
      out.write("        tooltip: {\r\n");
      out.write("          backgroundColor: '#0b1c10',\r\n");
      out.write("          titleFont: { family: \"'Inter',sans-serif\", weight: '700', size: 11 },\r\n");
      out.write("          bodyFont:  { family: \"'Inter',sans-serif\", size: 11 },\r\n");
      out.write("          padding: 11, cornerRadius: 10,\r\n");
      out.write("          callbacks: { label: function(ctx) { return ' Rs ' + ctx.raw.toLocaleString(); } }\r\n");
